// Calculate Final Combined Score & Assign Tier
const candidate = $('Anti-Bias Anonymizer').first().json.candidate;
const skillsResultText = $('Groq AI Skills Evaluator Chain').first().json.text || "{}";
const redFlagsResultText = $('Groq AI Red Flag Chain').first().json.text || "{}";

let skills = {};
let redFlags = {};
try {
  skills = JSON.parse(skillsResultText.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) {
  skills = { skills_score: 20, experience_score: 15, education_score: 5, salary_score: 5, bonus_score: 0 };
}

try {
  redFlags = JSON.parse(redFlagsResultText.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) {
  redFlags = { red_flags: [], has_critical_flag: false };
}

const totalScore = (skills.skills_score || 0) + 
                   (skills.experience_score || 0) + 
                   (skills.education_score || 0) + 
                   (skills.salary_score || 0) + 
                   (skills.bonus_score || 0);

let tier = "D";
if (totalScore >= 75) tier = "A";
else if (totalScore >= 55) tier = "B";
else if (totalScore >= 35) tier = "C";
else tier = "D";

let rejectionReason = "";
if (tier === "D") {
  rejectionReason = `we were looking for candidate profiles aligning closely with ${candidate.position} requirements, and your experience/skills match scored ${totalScore}/100.`;
}

const scoredCandidate = {
  ...candidate,
  overall_score: totalScore,
  tier: tier,
  skills_score: skills.skills_score || 0,
  experience_score: skills.experience_score || 0,
  education_score: skills.education_score || 0,
  salary_score: skills.salary_score || 0,
  culture_fit_score: skills.bonus_score || 0,
  red_flags: JSON.stringify(redFlags.red_flags || []),
  rejection_reason: rejectionReason,
  stage: "screened",
  status: tier === "D" ? "rejected" : "shortlisted",
  last_updated: new Date().toISOString()
};

return [{
  json: scoredCandidate
}];

