// FIX BUG 5: Replace Execute Workflow Trigger with Score Calculator & Tier Router
// FIX BUG 13: Output flat interview object at top level so Log Interview in Sheets works correctly
//   Candidate and calendly_link are also included at top level for use by email templates
const candidate = $('Score Calculator & Tier Router').first().json;
const questionsText = $input.first().json.text || "{}";

let questions = {};
try {
  questions = JSON.parse(questionsText.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) {
  questions = { technical_questions: ["Describe your experience with key stack technologies."], behavioral_questions: ["Tell me about a challenging project."] };
}

const interviewId = `INT_${Date.now()}_${Math.floor(100 + Math.random()*900)}`;
const calendlyLink = "https://calendly.com/hiring-team/first-round-interview";

// Flat interview record for Log Interview in Sheets (autoMapInputData)
const interviewPayload = {
  interview_id: interviewId,
  candidate_id: candidate.candidate_id,
  job_id: candidate.job_id,
  interview_type: "First Round Video",
  scheduled_date: "Pending Candidate Booking",
  scheduled_time: "Pending",
  duration_minutes: 45,
  interviewer_name: "Hiring Lead",
  interviewer_email: "interviewer@company.com",
  format: "video",
  video_link: calendlyLink,
  status: "scheduled",
  overall_recommendation: "",
  technical_score: 0,
  communication_score: 0,
  problem_solving_score: 0,
  culture_fit_score: 0,
  strengths: "",
  concerns: "",
  specific_examples: "",
  salary_recommendation: "",
  next_step: "",
  feedback_submitted_at: ""
};

// Output includes flat interview fields AND nested candidate/questions for email template access
return [{
  json: {
    ...interviewPayload,
    candidate: candidate,
    questions: questions,
    calendly_link: calendlyLink
  }
}];

// Filter interviews due for 24h email or 1h reminder
const items = $input.all();
const now = new Date();

const dueReminders = [];
items.forEach(item => {
  const row = item.json;
  const scheduledDate = new Date(row.scheduled_date);
  const diffMs = scheduledDate.getTime() - now.getTime();
  const diffHours = diffMs / (1000 * 60 * 60);

  if (diffHours > 23 && diffHours <= 25) {
    dueReminders.push({ ...row, reminder_type: '24h_email' });
  } else if (diffHours > 0.5 && diffHours <= 1.5) {
    dueReminders.push({ ...row, reminder_type: '1h_urgent' });
  }
});

return dueReminders.map(r => ({ json: r }));

// Process cancellation or no-show details
// FIX BUG 12: Calendly v2 webhook payload is at top-level $json, NOT nested in $json.body
// Calendly sends: { event: '...', payload: { invitee: { email: '...' }, cancellation: { reason: '...' } } }
const payload = $input.first().json.payload || {};
const invitee = payload.invitee || {};
const cancellation = payload.cancellation || {};
const email = invitee.email || "";

return [{
  json: {
    email: email,
    invitee_name: invitee.name || "",
    cancellation_reason: cancellation.reason || "No reason provided",
    event_type: payload.event_type?.name || "Interview"
  }
}];

const form = $input.first().json;
const timestamp = new Date().toISOString();

return [{
  json: {
    candidate_id: form["Candidate ID"],
    interviewer_name: form["Interviewer Name"],
    overall_recommendation: form["Overall Recommendation"],
    technical_score: Number(form["Technical Score (1-5)"] || 0),
    communication_score: Number(form["Communication Score (1-5)"] || 0),
    problem_solving_score: Number(form["Problem Solving Score (1-5)"] || 0),
    culture_fit_score: Number(form["Culture Fit Score (1-5)"] || 0),
    strengths: form["Strengths Observed"] || "",
    concerns: form["Concerns or Gaps"] || "",
    status: "completed",
    feedback_submitted_at: timestamp
  }
}];

