const candidates = $input.all().map(i => i.json);
const today = new Date().toISOString().split('T')[0];

let newApps = 0;
let tierA = 0, tierB = 0, tierC = 0, tierD = 0;

candidates.forEach(c => {
  if (c.tier === 'A') tierA++;
  else if (c.tier === 'B') tierB++;
  else if (c.tier === 'C') tierC++;
  else if (c.tier === 'D') tierD++;
});

return [{
  json: {
    date: today,
    new_applications: candidates.length,
    screened: candidates.length,
    tier_a: tierA,
    tier_b: tierB,
    tier_c: tierC,
    tier_d: tierD,
    interviews_scheduled: tierA,
    interviews_completed: 0,
    offers_sent: 0,
    offers_accepted: 0,
    hires_made: 0,
    by_source_json: "{}",
    by_position_json: "{}"
  }
}];

// FIX BUG 17: Aggregate all daily rows from the past 7 days instead of reading only the last row
const rows = $input.all().map(i => i.json);
const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

const weekly = rows.filter(r => r.date >= sevenDaysAgo);

const totals = weekly.reduce((acc, r) => {
  acc.new_applications += Number(r.new_applications || 0);
  acc.screened += Number(r.screened || 0);
  acc.tier_a += Number(r.tier_a || 0);
  acc.tier_b += Number(r.tier_b || 0);
  acc.tier_c += Number(r.tier_c || 0);
  acc.tier_d += Number(r.tier_d || 0);
  acc.interviews_scheduled += Number(r.interviews_scheduled || 0);
  acc.interviews_completed += Number(r.interviews_completed || 0);
  acc.offers_sent += Number(r.offers_sent || 0);
  acc.offers_accepted += Number(r.offers_accepted || 0);
  acc.hires_made += Number(r.hires_made || 0);
  return acc;
}, { new_applications: 0, screened: 0, tier_a: 0, tier_b: 0, tier_c: 0, tier_d: 0, interviews_scheduled: 0, interviews_completed: 0, offers_sent: 0, offers_accepted: 0, hires_made: 0 });

totals.week_start = sevenDaysAgo;
totals.days_included = weekly.length;

return [{ json: totals }];

